mapper.select:


    appInfo.deleted_flag = 'N'
    and appInfo.app_key = #{appKey}
    and appInfo.app_secret = #{appSecret}
    and appInfo.app_name like concat('%', #{appName}, '%')
    and appInfo.code = #{code}
    and appInfo.type = #{type}
    and appInfo.user_id = #{userId}
    and appInfo.status = #{status}
    and appInfo.remark like concat('%', #{remark}, '%')
    and appInfo.organization_id =
        #{organizationId}


        and

            (
            appInfo.remark like concat('%', #{item}, '%')
            )



order by appInfo.sort desc

select appInfo.id, appInfo.app_key, appInfo.app_secret, appInfo.icon, appInfo.app_name, appInfo.code, appInfo.type, appInfo.user_id, appInfo.status, appInfo.remark, appInfo.sort, appInfo.app_path, appInfo.pc_path, appInfo.organization_id from system_app_info as appInfo left join system_organization_app as organization on appInfo.id = organization.app_id
appInfo.deleted_flag = 'N' and appInfo.status = 1 and organization.deleted_flag = 'N' and organization.status = 1 and organization.organization_id = #{organizationId}
order by appInfo.sort desc

select DISTINCT appInfo.id, appInfo.app_key, appInfo.app_secret, appInfo.icon, appInfo.app_name, appInfo.code, appInfo.type, appInfo.user_id, appInfo.status, appInfo.remark, appInfo.sort, appInfo.app_path, appInfo.pc_path, appInfo.organization_id from system_app_info as appInfo left join system_organization_app as organization on appInfo.id = organization.app_id left join system_role_menu as role on appInfo.id = role.app_id left join system_role_user as ruser on ruser.role_id = role.role_id left join system_role as role1 on role1.id = role.role_id
appInfo.deleted_flag = 'N' and appInfo.status = 1 and role1.deleted_flag = 'N' and role1.status = 1 and role.deleted_flag = 'N' and ruser.deleted_flag = 'N' and role1.status = 1 and organization.deleted_flag = 'N' and organization.status = 1 and ruser.user_id = #{userId} and organization.organization_id = #{organizationId}
order by appInfo.sort desc
